    },
    {
      "year": 2050,
      "event": "Peak Fossil Fuel Usage",
      "detail": "Global efforts to mitigate climate change and the development of renewable energy sources lead to a peak and subsequent decline in the use of fossil fuels, reducing carbon emissions and environmental impacts."
    },
    {
      "year": 2060,
      "event": "Major Breakthrough in Fusion Energy",
      "detail": "A significant advancement in fusion power technology provides a virtually limitless and clean energy source, revolutionizing energy production and distribution."
    },
    {
