    {
      "year": 2300,
      "event": "First Interstellar Mission",
      "detail": "Humanity launches its first interstellar mission, sending a robotic probe to a nearby star system, with the aim of exploring potential habitable exoplanets."
    },
    {
      "year": 2500,
      "event": "Climate Restoration Efforts",
      "detail": "Advanced geoengineering technologies are employed to actively restore Earth's climate, reversing some of the damage caused by centuries of industrialization and climate change."
    },
