    {
      "year": 4000,
      "event": "Galactic Colonization",
      "detail": "Humanity begins colonizing multiple star systems, establishing a network of colonies and habitats throughout the Milky Way, with each colony developing its own unique culture and society."
    },
    {
      "year": 5000,
      "event": "Post-Scarcity Society Emerges",
      "detail": "Advanced automation, renewable energy, and resource management systems lead to a post-scarcity economy, where basic needs are met for all, and society focuses on creativity, personal growth, and exploration."
    },
    {
      "year": 6000,
      "event": "Intergalactic Exploration Begins",
      "detail": "Humanity launches its first mission to another galaxy, embarking on a multi-generational journey to explore and potentially colonize distant star systems."
    },
